WITH base AS (SELECT funnel_windowfunnel_user_levels.tenant_id AS `tenantId`, COUNT(DISTINCT if((funnel_windowfunnel_user_levels.funnel_level >= 1), funnel_windowfunnel_user_levels.user_id, NULL)) AS `loggedIn`, COUNT(DISTINCT if((funnel_windowfunnel_user_levels.funnel_level >= 2), funnel_windowfunnel_user_levels.user_id, NULL)) AS `ranQuery`, COUNT(DISTINCT if((funnel_windowfunnel_user_levels.funnel_level >= 3), funnel_windowfunnel_user_levels.user_id, NULL)) AS `exported` FROM funnel_windowfunnel_user_levels WHERE toDateTime64(funnel_windowfunnel_user_levels.month, 9, 'UTC') BETWEEN ? AND ? GROUP BY `tenantId`) SELECT `tenantId`, `loggedIn`, `ranQuery`, `exported`, (toFloat64(`ranQuery`) / NULLIF(`loggedIn`, 0)) AS `queryRate`, (toFloat64(`exported`) / NULLIF(`ranQuery`, 0)) AS `exportRate`, (toFloat64(`exported`) / NULLIF(`loggedIn`, 0)) AS `conversion` FROM base ORDER BY `loggedIn` DESC, `tenantId` ASC LIMIT 10
